import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Label,
  Progress,
  Alert,
} from "reactstrap";
import { useState, useEffect } from "react";
import { db, auth } from "../../firebase";
import { collection, addDoc, doc, getDoc, updateDoc } from "firebase/firestore";

const CarbonDataInput = () => {
  const [carbonData, setCarbonData] = useState({
    date: "",
    category: "",
    value: "",
    unit: "",
    carbonEmission: 0,
  });
  const [impactLevel, setImpactLevel] = useState("Low");
  const [submitted, setSubmitted] = useState(false);
  const [carbonStats, setCarbonStats] = useState({
    carbonCredits: 0,
    reductionProgress: 0,
    rank: "Beginner",
  });

  useEffect(() => {
    if (auth.currentUser) {
      fetchUserStats();
    }
  }, [auth.currentUser]);

  const fetchUserStats = async () => {
    const userRef = doc(db, "users", auth.currentUser.uid);
    const docSnap = await getDoc(userRef);
    if (docSnap.exists()) {
      setCarbonStats(docSnap.data());
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    const updatedData = { ...carbonData, [name]: value };

    if (name === "value" || name === "category") {
      const calculatedEmission = calculateCarbonEmissions(updatedData.category, parseFloat(value) || 0);
      updatedData.carbonEmission = calculatedEmission;
      setImpactLevel(getImpactLevel(calculatedEmission));
    }

    setCarbonData(updatedData);
  };

  const calculateCarbonEmissions = (category, value) => {
    switch (category) {
      case "Transport":
        return value * 2.31;
      case "Electricity":
        return value * 0.92;
      case "Diet":
        return value * 3.5;
      case "Waste":
        return value * 0.75;
      default:
        return 0;
    }
  };

  const getImpactLevel = (emission) => {
    if (emission <= 10) return "Low";
    if (emission > 10 && emission <= 50) return "Moderate";
    return "High";
  };

  const calculateCarbonCredits = (emission) => {
    return (emission / 10).toFixed(2);
  };

  const determineRank = (credits) => {
    if (credits < 50) return "Beginner";
    if (credits >= 50 && credits < 100) return "Intermediate";
    return "Expert";
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!auth.currentUser) {
      alert("Please log in to save your data.");
      return;
    }

    try {
      const carbonCredits = calculateCarbonCredits(carbonData.carbonEmission);
      const newCredits = carbonStats.carbonCredits + parseFloat(carbonCredits);
      const newRank = determineRank(newCredits);
      const newReductionProgress = (newCredits / 100) * 100;

      await addDoc(collection(db, "carbon_logs"), {
        userId: auth.currentUser.uid,
        date: carbonData.date,
        category: carbonData.category,
        value: carbonData.value,
        unit: carbonData.unit,
        carbonEmission: carbonData.carbonEmission,
      });

      const userRef = doc(db, "users", auth.currentUser.uid);
      await updateDoc(userRef, {
        carbonCredits: newCredits,
        reductionProgress: newReductionProgress,
        rank: newRank,
      });

      setSubmitted(true);
      setTimeout(() => setSubmitted(false), 3000);
      fetchUserStats();
      setCarbonData({ date: "", category: "", value: "", unit: "", carbonEmission: 0 });
    } catch (error) {
      console.error("Error saving data:", error);
      alert("Failed to save data. Please try again.");
    }
  };

  return (
    <Container className="mt-5" fluid>
      <Row className="justify-content-center">
        <Col lg="8">
          <Card className="bg-dark text-white shadow-lg">
            <CardHeader className="bg-gradient-info text-center">
              <h3 className="mb-0 text-white">Carbon Data Input</h3>
            </CardHeader>
            <CardBody>
              <Form>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Date</Label>
                      <Input type="date" name="date" value={carbonData.date} onChange={handleChange} required />
                    </FormGroup>
                  </Col>
                  <Col md="6">
                    <FormGroup>
                      <Label>Activity Category</Label>
                      <Input type="select" name="category" value={carbonData.category} onChange={handleChange} required>
                        <option value="">Select Category</option>
                        <option value="Transport">Transport</option>
                        <option value="Electricity">Electricity</option>
                        <option value="Diet">Diet</option>
                        <option value="Waste">Waste</option>
                      </Input>
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md="12" className="text-center mt-3">
                    <h4>Carbon Credits Earned: {carbonStats.carbonCredits.toFixed(2)}</h4>
                    <h4>Carbon Reduction Progress: {carbonStats.reductionProgress.toFixed(2)}%</h4>
                    <h4>Rank: {carbonStats.rank}</h4>
                  </Col>
                </Row>
                <Row className="text-center mt-4">
                  <Col>
                    <Button color="success" size="lg" className="px-5 shadow-lg" type="submit" onClick={handleSubmit}>
                      Save Data
                    </Button>
                  </Col>
                </Row>
              </Form>
              {submitted && <Alert color="success" className="text-center mt-3">✅ Data saved successfully!</Alert>}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default CarbonDataInput;
